mod solution;

fn main() {
    let cases = [
    (r#"values=[3,2,0,-4] tail->1"#, r#"true"#),
    (r#"values=[1,2,3] tail->none"#, r#"false"#),
    (r#"
values=[1,2,3] tail->none
"#, r#"false"#),
    (r#"  
values=[3,2,0,-4] tail->1
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS list-cycle");
}
